class Solution {
    struct TrieNode {
        TrieNode* children[26] = {};
        string word = "";
    };
public:
    string replaceWords(vector<string>& dictionary, string sentence) {
        TrieNode* root = new TrieNode();
        for (const string& dict : dictionary) {
            TrieNode* curr = root;
            for (char c : dict) {
                int idx = c - 'a';
                if (!curr->children[idx]) curr->children[idx] = new TrieNode();
                curr = curr->children[idx];
            }
            curr->word = dict;
        }

        stringstream ss(sentence);
        string word, res = "";
        while (ss >> word) {
            if (!res.empty()) res += " ";
            TrieNode* curr = root;
            string match = word;
            for (char c : word) {
                int idx = c - 'a';
                if (!curr->children[idx]) break;
                curr = curr->children[idx];
                if (!curr->word.empty()) {
                    match = curr->word;
                    break;
                }
            }
            res += match;
        }
        return res;
    }
};

class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word = null;
    }
    public String replaceWords(List<String> dictionary, String sentence) {
        TrieNode root = new TrieNode();
        for (String dict : dictionary) {
            TrieNode curr = root;
            for (char c : dict.toCharArray()) {
                int idx = c - 'a';
                if (curr.children[idx] == null) curr.children[idx] = new TrieNode();
                curr = curr.children[idx];
            }
            curr.word = dict;
        }

        String[] words = sentence.split(" ");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            if (i > 0) sb.append(" ");
            TrieNode curr = root;
            String match = words[i];
            for (char c : words[i].toCharArray()) {
                int idx = c - 'a';
                if (curr.children[idx] == null) break;
                curr = curr.children[idx];
                if (curr.word != null) {
                    match = curr.word;
                    break;
                }
            }
            sb.append(match);
        }
        return sb.toString();
    }
}

var replaceWords = function(dictionary, sentence) {
    const root = {};
    for (const dict of dictionary) {
        let curr = root;
        for (const ch of dict) {
            if (!curr[ch]) curr[ch] = {};
            curr = curr[ch];
        }
        curr['#'] = dict;
    }

    const words = sentence.split(' ');
    const res = words.map(word => {
        let curr = root;
        for (const ch of word) {
            if (!curr[ch]) break;
            curr = curr[ch];
            if (curr['#']) return curr['#'];
        }
        return word;
    });
    return res.join(' ');
};
